package com.ahotel.controller;import com.ahotel.model.Booking;import com.ahotel.service.BookingService;import org.springframework.web.bind.annotation.*;import java.util.List;@RestController @RequestMapping("/api/bookings") public class BookingApiController {private final BookingService s;public BookingApiController(BookingService s){this.s=s;}@GetMapping public List<Booking> all(){return s.findAll();}@PostMapping public String create(@RequestBody Booking b){s.create(b);return "Booking created";}}